mapper.select:

SELECT MAX(frozen_at) FROM (
  SELECT MAX(created_at) AS frozen_at FROM ai_task WHERE owner_id=#{owner}
  UNION ALL SELECT MAX(started_at) FROM memory_recall_attempt WHERE owner_id=#{owner}
  UNION ALL SELECT MAX(occurred_at) FROM memory_attempt_event WHERE owner_id=#{owner} AND event_kind='RATE'
  UNION ALL SELECT MAX(created_at) FROM knowledge_revalidation_event WHERE owner_id=#{owner}
  UNION ALL SELECT MAX(created_at) FROM preparation_knowledge_event WHERE owner_id=#{owner}
) frozen

SELECT s.task_id,s.source_item_id,s.source_version_id,source.version_number AS source_version_number,
  d.target_item_id,d.target_version_id,target.version_number AS target_version_number
FROM ai_knowledge_source s JOIN ai_candidate_decision d
  ON d.owner_id=s.owner_id AND d.task_id=s.task_id AND d.status='ADOPTED'
JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='KNOWLEDGE_DRAFT'
JOIN knowledge_version source ON source.owner_id=s.owner_id AND source.item_id=s.source_item_id AND source.id=s.source_version_id
JOIN knowledge_version target ON target.owner_id=d.owner_id AND target.item_id=d.target_item_id AND target.id=d.target_version_id
WHERE s.owner_id=#{owner} AND s.source_item_id=#{sourceItemId} AND source.version_number >= #{minimumVersion}
AND s.task_id > #{after}
ORDER BY s.task_id LIMIT #{limit}

SELECT EXISTS(SELECT 1 FROM knowledge_revalidation_impact
  WHERE owner_id=#{owner} AND event_id=#{eventId} AND task_id=#{taskId}
    AND source_item_id=#{sourceItemId} AND source_version_id=#{sourceVersionId})

SELECT 

WHERE i.owner_id=#{owner}

  AND i.root_item_id=#{itemId}
  AND i.target_item_id=#{itemId}
  AND 1=0

AND i.revision=0

  AND (i.created_at < #{beforeTime} OR (i.created_at=#{beforeTime} AND i.id < #{beforeId}))

ORDER BY i.created_at DESC,i.id DESC LIMIT #{limit}
